hooks.command:
if [ -f "${PLUGIN_ROOT}/scripts/loom_checker.py" ]; then exec python3 "${PLUGIN_ROOT}/scripts/loom_checker.py" push --hook; else exec python3 -c 'import json, os, re, sys
checker = os.path.join(os.environ.get("PLUGIN_ROOT", ""), "scripts", "loom_checker.py")
failed = f"installed checker is unavailable at {checker}; restart Codex to load the installed plugin version"
def deny(why):
 print(f"BLOCK selection.guard: {why} ({failed})", file=sys.stderr)
 raise SystemExit(2)
try:
 payload = json.load(sys.stdin)
 fields = {k: v for k, v in (payload.get("tool_input") or {}).items() if isinstance(v, str)}
except (ValueError, TypeError, AttributeError):
 deny("hook payload is unreadable")
if payload.get("tool_name") in {"Write", "Edit", "MultiEdit", "NotebookEdit", "apply_patch"}:
 targets = [v for k, v in fields.items() if k in {"file_path", "notebook_path"}]
 targets += [t for v in fields.values() for t in re.findall(r"^\*\*\* (?:Add File|Update File|Delete File|Move to): (.+?)\s*$", v, re.M)]
 if any("loom/selections" in t for t in targets): deny("targets the selection record store")
 raise SystemExit(0)
if "loom/selections" in fields.get("command", ""): deny("names the selection record store")
print(f"loom: publication hook failed ({failed}); allowing.", file=sys.stderr)' ; fi

